#!/usr/bin/env node
/**
 * Exports validated evolution champions into js/ai/evolved-profiles.js.
 *
 * Usage: node scripts/export-champions.js evolution/<runId>
 *
 * Reads validation.json + archive.json + config.json from the run, keeps champions with ok=true, names them by
 * their MAP-Elites cell (aggression bin : game-length bin), and splits them into normal/hard tiers by held-out score.
 * The output is a generated file: re-run instead of hand-editing.
 */
const fs = require('fs');
const path = require('path');

const runDir = process.argv[2];
if (!runDir) {
	console.error('usage: node scripts/export-champions.js evolution/<runId>');
	process.exit(1);
}
const read = f => JSON.parse(fs.readFileSync(path.join(runDir, f), 'utf8'));
const validation = read('validation.json');
const archive = read('archive.json');
const config = read('config.json');

const AGGRESSION = ['cautious', 'balanced', 'ruthless'];
const LENGTH = ['swift', 'steady', 'grinding'];
const NAMES = {
	'0:0': 'Silent Blade', '0:1': 'Iron Wall', '0:2': 'Patient Tide',
	'1:0': 'Quick Gambit', '1:1': 'Steady Hand', '1:2': 'Long Siege',
	'2:0': 'Lightning Raid', '2:1': 'Red Banner', '2:2': 'Blood Marathon',
};
const slug = name => 'evolved_' + name.toLowerCase().replace(/[^a-z]+/g, '_');

const champions = validation.filter(v => v.ok).sort((a, b) => a.heldSeeds - b.heldSeeds).map(v => {
	const [a, l] = v.cell.split(':').map(Number);
	const name = NAMES[v.cell] || `Champion ${v.cell}`;
	const profile = { ...archive[v.cell].profile };
	profile.name = name;
	profile.description = `${AGGRESSION[a]}, ${LENGTH[l]} games: ${v.desc.aggression.toFixed(2)} kills per action, ~${Math.round(v.desc.length)} plies per game, ${Math.round(v.vsBaseline * 100)}% vs Baseline.`;
	profile.evolved = true;
	return { key: slug(name), profile };
});
if (champions.length < 2) {
	console.error('fewer than 2 passing champions; refusing to export');
	process.exit(1);
}
const mid = Math.floor(champions.length / 2);
const tiers = { normal: champions.slice(0, mid).map(c => c.key), hard: champions.slice(mid).map(c => c.key) };

const out = `/**
 * GENERATED by scripts/export-champions.js from ${runDir} (seed ${config.seed}, ${config.gens} generations, pop ${config.pop}).
 * Do not edit by hand. Champions are ordered weakest -> strongest by held-out score.
 * Loaded after heuristic-profiles.js; getProfile() falls back to these, so random AI picks are unchanged.
 */
const evolvedProfiles = ${JSON.stringify(Object.fromEntries(champions.map(c => [c.key, c.profile])), null, '\t')};

const EVOLVED_ORDER = ${JSON.stringify(champions.map(c => c.key))};

const AI_TIERS = ${JSON.stringify(tiers, null, '\t')};
`;
fs.writeFileSync(path.join(__dirname, '..', 'js', 'ai', 'evolved-profiles.js'), out);
console.log(`exported ${champions.length} champions: ${champions.map(c => c.key).join(', ')}`);
console.log(`normal: ${tiers.normal}\nhard: ${tiers.hard}`);
